#!/usr/bin/env bash
set -euo pipefail
V=7.0.0; R="$(cd "$(dirname "$0")" && pwd)"; T="$R/.ocr-tmp"; O="$R/vendor/tesseract"; rm -rf "$T" "$O"; mkdir -p "$T/js" "$T/core" "$O/core" "$O/lang-data"; npm pack "tesseract.js@$V" --pack-destination "$T"; npm pack "tesseract.js-core@$V" --pack-destination "$T"; tar -xzf "$T"/tesseract.js-*.tgz -C "$T/js"; tar -xzf "$T"/tesseract.js-core-*.tgz -C "$T/core"; cp "$T/js/package/dist/tesseract.min.js" "$O/"; cp "$T/js/package/dist/worker.min.js" "$O/"; N=""; for n in tesseract-core-simd-lstm.wasm.min.js tesseract-core-simd-lstm.wasm.js; do [ -f "$T/core/package/$n" ] && N="$n" && break; done; [ -n "$N" ] || { echo "SIMD LSTM Core not found"; exit 1; }; cp "$T/core/package/$N" "$O/core/"; W="${N%.min.js}"; W="${W%.js}"; [ -f "$T/core/package/$W" ] || W=tesseract-core-simd-lstm.wasm; cp "$T/core/package/$W" "$O/core/"; curl -L --fail --retry 3 -o "$O/lang-data/eng.traineddata.gz" https://tessdata.projectnaptha.com/4.0.0_fast/eng.traineddata.gz; printf "window.OCR_CORE_PATH='./vendor/tesseract/core/%s';\n" "$N" > "$R/ocr-config.js"; rm -rf "$T"; du -sh "$O"
